const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>'<span class="bundle-seed"></span>';
// Each seed appears in exactly one physical location. An outline is never a counter.
export function bundleTable(model,{label='Working exchange table',total=model.wrapped*10+model.loose+model.frame}={}){
 const {wrapped,loose,frame}=model;
 return `<figure class="bundle-table" aria-label="${esc(label)}"><figcaption>${esc(label)}: ${total} individual counters altogether</figcaption><div class="bundle-table-places"><section class="bundle-shelf"><h3>Wrapped shelf</h3><div class="bundle-wrapped" role="img" aria-label="${wrapped} wrapped ${wrapped===1?'bundle':'bundles'}, each containing ten individual counters">${Array.from({length:wrapped},()=>`<span class="bundle-packet" aria-hidden="true">${Array.from({length:10},seed).join('')}</span>`).join('')}</div><p>${wrapped} wrapped ${wrapped===1?'bundle':'bundles'}${wrapped===0?'; the shelf is empty':''}.</p></section><section class="bundle-frame-place"><h3>Ten-place frame</h3><div class="bundle-frame" role="img" aria-label="${frame} individual counters in ten positions, two rows of five; ${frame===10?'full and still unwrapped':`${10-frame} empty positions`}">${Array.from({length:10},(_,i)=>`<span class="bundle-slot" aria-hidden="true">${i<frame?seed():''}</span>`).join('')}</div><p>${frame} individual counters. ${frame===10?'Full; these ten are not wrapped.':frame===0?'The frame is empty.':'Still individual counters.'}</p></section><section class="bundle-loose-place"><h3>Loose tray</h3><div class="bundle-loose" role="img" aria-label="${loose} loose individual counters">${Array.from({length:loose},seed).join('')}</div><p>${loose} loose individual counters${loose===0?'; the tray is empty':''}.</p></section></div><p class="bundle-table-summary">Summary of this picture: ${wrapped} wrapped ${wrapped===1?'ten':'tens'}, ${loose} loose ones, ${frame} frame ones; ${total} individual counters in all. Each outline holds counters; it does not add one.</p></figure>`;
}
export function canonicalExample(model,total){return model.frame===0&&model.loose<10&&[13,16,20,27,30,42].includes(total)?`bundle:0:${model.wrapped}:${model.loose}`:null;}
